import React from 'react';

export const CarIcon = ({ color = "#00E5FF", width = 60, height = 40 }: { color?: string; width?: number; height?: number }) => (
    <svg width={width} height={height} viewBox="0 0 120 80" fill="none" xmlns="http://www.w3.org/2000/svg">
        <defs>
            <linearGradient id="bodyGradient" x1="60" y1="15" x2="60" y2="72" gradientUnits="userSpaceOnUse">
                <stop stopColor={color} stopOpacity="0.85" />
                <stop offset="1" stopColor="#05060A" stopOpacity="0.95" />
            </linearGradient>
            <filter id="neonGlow" x="-50%" y="-50%" width="200%" height="200%">
                <feGaussianBlur stdDeviation="3" result="coloredBlur" />
                <feMerge>
                    <feMergeNode in="coloredBlur" />
                    <feMergeNode in="SourceGraphic" />
                </feMerge>
            </filter>
        </defs>

        {/* Thick, realistic rear slicks */}
        <rect x="15" y="45" width="22" height="32" rx="4" fill="#050505" />
        <rect x="83" y="45" width="22" height="32" rx="4" fill="#050505" />

        {/* Sleek, curved supercar silhouette (wide fenders, tapered cabin) */}
        <path
            d="M8 55 C8 40, 20 34, 30 33 C35 18, 48 14, 60 14 C72 14, 85 18, 90 33 C100 34, 112 40, 112 55 L112 65 C112 70, 107 72, 100 72 L20 72 C13 72, 8 70, 8 65 Z"
            fill="url(#bodyGradient)"
            stroke={color}
            strokeWidth="1"
        />

        {/* Smooth, dark rear windshield */}
        <path d="M34 34 C42 19, 52 17, 60 17 C68 17, 78 19, 86 34 Z" fill="#0A0C10" stroke="#1A202C" strokeWidth="1" opacity="0.9" />

        {/* Underbody Diffuser */}
        <path d="M30 72 L38 58 H82 L90 72 Z" fill="#030303" stroke="#111" strokeWidth="1" />

        {/* Minimalist LED Strip Taillights */}
        <path d="M16 48 H46" stroke="#FF0040" strokeWidth="3" strokeLinecap="round" filter="url(#neonGlow)" />
        <path d="M74 48 H104" stroke="#FF0040" strokeWidth="3" strokeLinecap="round" filter="url(#neonGlow)" />

        {/* Glowing Engine Accent / Emblem */}
        <line x1="56" y1="48" x2="64" y2="48" stroke={color} strokeWidth="2" strokeLinecap="round" opacity="0.8" filter="url(#neonGlow)" />

        {/* Exhaust Pipes */}
        <circle cx="45" cy="65" r="4.5" fill="#111" stroke="#333" strokeWidth="1.5" />
        <circle cx="75" cy="65" r="4.5" fill="#111" stroke="#333" strokeWidth="1.5" />

        {/* Blue flame exhaust glow (animated) */}
        <circle cx="45" cy="65" r="2" fill="#00E5FF" filter="url(#neonGlow)">
            <animate attributeName="opacity" values="0.2;1;0.2" dur="0.12s" repeatCount="indefinite" />
        </circle>
        <circle cx="75" cy="65" r="2" fill="#00E5FF" filter="url(#neonGlow)">
            <animate attributeName="opacity" values="0.2;1;0.2" dur="0.14s" repeatCount="indefinite" begin="0.05s" />
        </circle>
    </svg>
);

export const GhostIcon = ({ type = "default", color = "white", opacity = 0.9 }: { type?: string, color?: string, opacity?: number }) => {
    const ghostColors: Record<string, { primary: string, secondary: string }> = {
        default: { primary: "white", secondary: "#00E5FF" },
        phantom: { primary: "#8BE9FD", secondary: "#6272A4" },
        reaper: { primary: "#FF5555", secondary: "#FF2A6D" },
        wraith: { primary: "#BD93F9", secondary: "#8B5CF6" },
        spectre: { primary: "#00FF87", secondary: "#00E5FF" },
        eternal: { primary: "#FFD700", secondary: "#FFA500" },
    };

    const c = ghostColors[type] || ghostColors.default;
    const uid = `ghost_${type}_${Math.random().toString(36).slice(2, 8)}`;

    if (type === "reaper") {
        return (
            <svg width="50" height="60" viewBox="0 0 50 60" fill="none" xmlns="http://www.w3.org/2000/svg" style={{ opacity }}>
                <defs>
                    <radialGradient id={`${uid}_core`} cx="0.5" cy="0.4" r="0.5">
                        <stop stopColor={c.primary} stopOpacity="0.6" />
                        <stop offset="1" stopColor={c.primary} stopOpacity="0" />
                    </radialGradient>
                    <filter id={`${uid}_glow`} x="-30%" y="-30%" width="160%" height="160%">
                        <feGaussianBlur stdDeviation="3" result="blur" />
                        <feComposite in="SourceGraphic" in2="blur" operator="over" />
                    </filter>
                </defs>
                {/* Angular hooded form */}
                <path d="M25 2L42 20L40 55L35 50L30 55L25 50L20 55L15 50L10 55L8 20L25 2Z"
                    fill={`url(#${uid}_core)`} stroke={c.primary} strokeWidth="1.5" filter={`url(#${uid}_glow)`} />
                {/* Scythe-like slash */}
                <path d="M5 15Q15 8 25 18Q35 28 45 20" stroke={c.secondary} strokeWidth="1" opacity="0.6" fill="none" />
                {/* Menacing eyes */}
                <path d="M17 22L22 25L17 28Z" fill={c.primary} opacity="0.9" />
                <path d="M33 22L28 25L33 28Z" fill={c.primary} opacity="0.9" />
                <circle cx="19" cy="25" r="1" fill="white">
                    <animate attributeName="opacity" values="1;0.3;1" dur="2s" repeatCount="indefinite" />
                </circle>
                <circle cx="31" cy="25" r="1" fill="white">
                    <animate attributeName="opacity" values="1;0.3;1" dur="2s" repeatCount="indefinite" />
                </circle>
            </svg>
        );
    }

    if (type === "phantom") {
        return (
            <svg width="50" height="60" viewBox="0 0 50 60" fill="none" xmlns="http://www.w3.org/2000/svg" style={{ opacity }}>
                <defs>
                    <radialGradient id={`${uid}_core`} cx="0.5" cy="0.4" r="0.6">
                        <stop stopColor={c.primary} stopOpacity="0.5" />
                        <stop offset="1" stopColor={c.secondary} stopOpacity="0" />
                    </radialGradient>
                    <filter id={`${uid}_glow`} x="-20%" y="-20%" width="140%" height="140%">
                        <feGaussianBlur stdDeviation="2.5" result="blur" />
                        <feComposite in="SourceGraphic" in2="blur" operator="over" />
                    </filter>
                </defs>
                {/* Smooth flowing form */}
                <path d="M15 55C15 55 10 40 13 22C16 4 34 4 37 22C40 40 35 55 35 55Q30 48 25 55Q20 48 15 55Z"
                    fill={`url(#${uid}_core)`} stroke={c.primary} strokeWidth="1.5" filter={`url(#${uid}_glow)`} />
                {/* Dual cold eyes */}
                <ellipse cx="20" cy="22" rx="3" ry="4" fill={c.primary} opacity="0.8" />
                <ellipse cx="30" cy="22" rx="3" ry="4" fill={c.primary} opacity="0.8" />
                <circle cx="20" cy="22" r="1.5" fill="white" />
                <circle cx="30" cy="22" r="1.5" fill="white" />
                {/* Fading particles */}
                <circle cx="18" cy="42" r="1" fill={c.secondary} opacity="0.4">
                    <animate attributeName="cy" values="42;52" dur="1.5s" repeatCount="indefinite" />
                    <animate attributeName="opacity" values="0.4;0" dur="1.5s" repeatCount="indefinite" />
                </circle>
                <circle cx="32" cy="45" r="0.8" fill={c.secondary} opacity="0.3">
                    <animate attributeName="cy" values="45;55" dur="1.8s" repeatCount="indefinite" />
                    <animate attributeName="opacity" values="0.3;0" dur="1.8s" repeatCount="indefinite" />
                </circle>
            </svg>
        );
    }

    if (type === "wraith") {
        return (
            <svg width="50" height="60" viewBox="0 0 50 60" fill="none" xmlns="http://www.w3.org/2000/svg" style={{ opacity }}>
                <defs>
                    <radialGradient id={`${uid}_core`} cx="0.5" cy="0.35" r="0.5">
                        <stop stopColor={c.primary} stopOpacity="0.7" />
                        <stop offset="1" stopColor={c.secondary} stopOpacity="0" />
                    </radialGradient>
                    <filter id={`${uid}_glow`} x="-30%" y="-30%" width="160%" height="160%">
                        <feGaussianBlur stdDeviation="4" result="blur" />
                        <feComposite in="SourceGraphic" in2="blur" operator="over" />
                    </filter>
                </defs>
                {/* Multi-layered swirl form */}
                <path d="M8 50C8 50 3 35 10 18C17 1 33 1 40 18C47 35 42 50 42 50" stroke={c.primary} strokeWidth="0.8" opacity="0.3" fill="none" />
                <path d="M12 52C12 52 7 38 12 22C17 6 33 6 38 22C43 38 38 52 38 52" stroke={c.primary} strokeWidth="1.5" fill={`url(#${uid}_core)`} filter={`url(#${uid}_glow)`} />
                {/* Spiraling energy */}
                <path d="M25 10Q35 20 25 30Q15 40 25 50" stroke={c.secondary} strokeWidth="1" opacity="0.5" fill="none">
                    <animate attributeName="opacity" values="0.3;0.7;0.3" dur="2s" repeatCount="indefinite" />
                </path>
                {/* Central eye vortex */}
                <circle cx="25" cy="22" r="5" stroke={c.primary} strokeWidth="1" fill="none" opacity="0.6">
                    <animate attributeName="r" values="4;6;4" dur="2s" repeatCount="indefinite" />
                </circle>
                <circle cx="25" cy="22" r="2" fill="white" opacity="0.9" />
                {/* Wisps */}
                <circle cx="15" cy="40" r="1.2" fill={c.primary} opacity="0.4">
                    <animate attributeName="cy" values="40;50" dur="1s" repeatCount="indefinite" />
                    <animate attributeName="opacity" values="0.4;0" dur="1s" repeatCount="indefinite" />
                </circle>
                <circle cx="35" cy="42" r="1" fill={c.secondary} opacity="0.3">
                    <animate attributeName="cy" values="42;52" dur="1.2s" repeatCount="indefinite" />
                    <animate attributeName="opacity" values="0.3;0" dur="1.2s" repeatCount="indefinite" />
                </circle>
                <circle cx="25" cy="46" r="0.8" fill={c.primary} opacity="0.5">
                    <animate attributeName="cy" values="46;56" dur="0.8s" repeatCount="indefinite" />
                    <animate attributeName="opacity" values="0.5;0" dur="0.8s" repeatCount="indefinite" />
                </circle>
            </svg>
        );
    }

    if (type === "spectre") {
        return (
            <svg width="50" height="60" viewBox="0 0 50 60" fill="none" xmlns="http://www.w3.org/2000/svg" style={{ opacity }}>
                <defs>
                    <linearGradient id={`${uid}_grad`} x1="25" y1="5" x2="25" y2="55" gradientUnits="userSpaceOnUse">
                        <stop stopColor={c.primary} stopOpacity="0.8" />
                        <stop offset="1" stopColor={c.secondary} stopOpacity="0.1" />
                    </linearGradient>
                    <filter id={`${uid}_glow`} x="-30%" y="-30%" width="160%" height="160%">
                        <feGaussianBlur stdDeviation="3" result="blur" />
                        <feComposite in="SourceGraphic" in2="blur" operator="over" />
                    </filter>
                </defs>
                {/* Crystalline geometric form */}
                <path d="M25 5L40 20L38 45L30 55L20 55L12 45L10 20L25 5Z"
                    fill={`url(#${uid}_grad)`} stroke={c.primary} strokeWidth="1" filter={`url(#${uid}_glow)`} opacity="0.6" />
                {/* Internal facets */}
                <path d="M25 5L12 45M25 5L38 45M10 20H40M20 55L25 30L30 55" stroke={c.primary} strokeWidth="0.5" opacity="0.3" />
                {/* Glowing vertices */}
                <circle cx="25" cy="5" r="1.5" fill={c.primary} />
                <circle cx="40" cy="20" r="1" fill={c.primary} opacity="0.7" />
                <circle cx="10" cy="20" r="1" fill={c.primary} opacity="0.7" />
                {/* Core light */}
                <circle cx="25" cy="25" r="4" fill="white" opacity="0.8" filter={`url(#${uid}_glow)`}>
                    <animate attributeName="r" values="3;5;3" dur="1.5s" repeatCount="indefinite" />
                    <animate attributeName="opacity" values="0.6;1;0.6" dur="1.5s" repeatCount="indefinite" />
                </circle>
            </svg>
        );
    }

    if (type === "eternal") {
        return (
            <svg width="50" height="60" viewBox="0 0 50 60" fill="none" xmlns="http://www.w3.org/2000/svg" style={{ opacity }}>
                <defs>
                    <radialGradient id={`${uid}_core`} cx="0.5" cy="0.4" r="0.5">
                        <stop stopColor={c.primary} stopOpacity="0.9" />
                        <stop offset="1" stopColor={c.secondary} stopOpacity="0" />
                    </radialGradient>
                    <filter id={`${uid}_glow`} x="-40%" y="-40%" width="180%" height="180%">
                        <feGaussianBlur stdDeviation="5" result="blur" />
                        <feComposite in="SourceGraphic" in2="blur" operator="over" />
                    </filter>
                </defs>
                {/* Radiant divine form */}
                <circle cx="25" cy="25" r="18" fill={`url(#${uid}_core)`} filter={`url(#${uid}_glow)`}>
                    <animate attributeName="r" values="16;20;16" dur="3s" repeatCount="indefinite" />
                </circle>
                {/* Halo ring */}
                <ellipse cx="25" cy="12" rx="14" ry="4" stroke={c.primary} strokeWidth="1.5" fill="none" opacity="0.7">
                    <animate attributeName="ry" values="3;5;3" dur="2s" repeatCount="indefinite" />
                </ellipse>
                {/* Crown points */}
                <path d="M15 12L18 5L21 10L25 3L29 10L32 5L35 12" stroke={c.primary} strokeWidth="1" fill="none" opacity="0.6" />
                {/* Central divine eye */}
                <circle cx="25" cy="22" r="6" fill={c.primary} opacity="0.3" />
                <circle cx="25" cy="22" r="3" fill="white" opacity="0.95">
                    <animate attributeName="opacity" values="0.8;1;0.8" dur="1s" repeatCount="indefinite" />
                </circle>
                {/* Cascading light trails */}
                <path d="M25 35V55" stroke={c.primary} strokeWidth="2" opacity="0.4">
                    <animate attributeName="opacity" values="0.2;0.6;0.2" dur="1.5s" repeatCount="indefinite" />
                </path>
                <path d="M18 32L12 52" stroke={c.secondary} strokeWidth="1" opacity="0.3">
                    <animate attributeName="opacity" values="0.1;0.4;0.1" dur="1.8s" repeatCount="indefinite" />
                </path>
                <path d="M32 32L38 52" stroke={c.secondary} strokeWidth="1" opacity="0.3">
                    <animate attributeName="opacity" values="0.1;0.4;0.1" dur="1.8s" repeatCount="indefinite" />
                </path>
            </svg>
        );
    }

    // Default: Wisp
    return (
        <svg width="50" height="60" viewBox="0 0 50 60" fill="none" xmlns="http://www.w3.org/2000/svg" style={{ opacity }}>
            <defs>
                <radialGradient id={`${uid}_core`} cx="0" cy="0" r="1" gradientUnits="userSpaceOnUse" gradientTransform="translate(25 30) rotate(90) scale(25 20)">
                    <stop stopColor={c.primary} stopOpacity="0.9" />
                    <stop offset="1" stopColor={c.primary} stopOpacity="0" />
                </radialGradient>
                <filter id={`${uid}_blur`} x="-20%" y="-20%" width="140%" height="140%">
                    <feGaussianBlur stdDeviation="3" result="blur" />
                    <feComposite in="SourceGraphic" in2="blur" operator="over" />
                </filter>
            </defs>
            <path d="M10 50C10 50 5 40 10 20C15 -5 35 -5 40 20C45 40 40 50 40 50" stroke={c.primary} strokeWidth="1" strokeOpacity="0.3" fill="none" />
            <path d="M15 55C15 55 12 45 15 25C18 5 32 5 35 25C38 45 35 55 35 55" stroke={c.primary} strokeWidth="2" strokeOpacity="0.6" fill={`url(#${uid}_core)`} filter={`url(#${uid}_blur)`} />
            <circle cx="25" cy="20" r="6" fill="white" fillOpacity="0.9" filter={`url(#${uid}_blur)`}>
                <animate attributeName="r" values="5;7;5" dur="1.5s" repeatCount="indefinite" />
                <animate attributeName="opacity" values="0.8;1;0.8" dur="1.5s" repeatCount="indefinite" />
            </circle>
            <circle cx="20" cy="45" r="1" fill={c.primary} opacity="0.5">
                <animate attributeName="cy" values="45;55" dur="1s" repeatCount="indefinite" />
                <animate attributeName="opacity" values="0.5;0" dur="1s" repeatCount="indefinite" />
            </circle>
            <circle cx="30" cy="48" r="1.5" fill={c.primary} opacity="0.5">
                <animate attributeName="cy" values="48;58" dur="1.2s" repeatCount="indefinite" />
                <animate attributeName="opacity" values="0.5;0" dur="1.2s" repeatCount="indefinite" />
            </circle>
        </svg>
    );
};

